func TestCheckAll(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/down" {
			w.WriteHeader(http.StatusServiceUnavailable)
		}
	}))
	defer srv.Close()

	checker := NewChecker(srv.Client(), clock.Fixed{T: time.Unix(0, 0)})

	tests := []struct {
		name string
		urls []string
		want []bool
	}{
		{"no urls", nil, []bool{}},
		{"one up", []string{srv.URL + "/up"}, []bool{true}},
		{"order is kept", []string{srv.URL + "/down", srv.URL + "/up", srv.URL + "/down"}, []bool{false, true, false}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := checker.CheckAll(context.Background(), tt.urls)
			if len(got) != len(tt.want) {
				t.Fatalf("CheckAll(%v) returned %d results, want %d", tt.urls, len(got), len(tt.want))
			}
			for i, r := range got {
				if r.URL != tt.urls[i] {
					t.Errorf("CheckAll(%v)[%d].URL = %q, want %q", tt.urls, i, r.URL, tt.urls[i])
				}
				if r.Healthy() != tt.want[i] {
					t.Errorf("CheckAll(%v)[%d].Healthy() = %v, want %v", tt.urls, i, r.Healthy(), tt.want[i])
				}
			}
		})
	}
}

